(()=>{'use strict';const $=s=>document.querySelector(s),state={section:'slides',records:[],selected:null};const KEY='mgd-panel-v1';const seed={slides:[{title:'Şuurlu Gençlik Güçlü Türkiye',summary:'Ahlak, ilim ve sorumlulukla yarınları birlikte inşa ediyoruz.',status:'published',sort_order:0,image_url:'../assets/youth.jpg'}],news:[]};let store=JSON.parse(localStorage.getItem(KEY)||'null')||seed;const saveStore=()=>localStorage.setItem(KEY,JSON.stringify(store));const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const status=(m,e=false)=>{$('#panel-status').textContent=m;$('#panel-status').className=e?'error':''};function showLogin(){$('#login').hidden=false;$('#panel').hidden=true}function showPanel(){$('#login').hidden=true;$('#panel').hidden=false;$('#account').textContent='admin';reload()}function reload(){state.records=store[state.section]||[];renderList();if(state.selected)fill(state.selected)}function renderList(){const q=$('#filter').value.toLocaleLowerCase('tr');const rows=state.records.filter(r=>!q||(`${r.title} ${r.summary}`).toLocaleLowerCase('tr').includes(q));$('#list').innerHTML=rows.length?rows.map((r,i)=>`<button class="record ${state.selected===r?'active':''}" data-index="${i}"><b>${esc(r.title||'Başlıksız içerik')}</b><small>${r.status==='published'?'Yayında':'Taslak'} · ${state.section==='slides'?'Slider':(r.category||'Haber')}</small></button>`).join(''):'<p id="empty">Henüz içerik yok.</p>';$('#list').querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{state.selected=state.records[Number(b.dataset.index)];fill(state.selected);renderList()})}function fill(r){$('#empty').hidden=true;$('#content-form').hidden=false;$('#form-title').textContent='İçerik düzenle';$('#title').value=r.title||'';$('#summary').value=r.summary||'';$('#button-label').value=r.button_label||'';$('#button-url').value=r.button_url||'';$('#sort-order').value=r.sort_order||0;$('#status').value=r.status||'draft';$('#category').value=r.category||'Haber';$('#published-at').value=r.published_at||'';$('#body').value=r.body||'';$('#preview-image').src=r.image_url||'';setMode();updatePreview()}function setMode(){document.querySelectorAll('.slider-only').forEach(e=>e.hidden=state.section!=='slides');document.querySelectorAll('.news-only').forEach(e=>e.hidden=state.section==='slides');$('#heading').textContent=state.section==='slides'?'Ana sayfa slider':'Haberler ve duyurular';$('#add').textContent=state.section==='slides'?'Yeni slider':'Yeni haber'}function updatePreview(){$('#preview-title').textContent=$('#title').value;$('#preview-summary').textContent=$('#summary').value;$('#preview-button').textContent=state.section==='slides'?($('#button-label').value||'Derneğimizi Tanıyın'):($('#category').value||'Haber')}function save(e){e.preventDefault();const r=state.selected||{};Object.assign(r,{title:$('#title').value.trim(),summary:$('#summary').value.trim(),button_label:$('#button-label').value.trim(),button_url:$('#button-url').value.trim(),sort_order:Number($('#sort-order').value||0),status:$('#status').value,category:$('#category').value,published_at:$('#published-at').value,body:$('#body').value.trim(),image_url:$('#image').dataset.url||r.image_url||''});if(!r.title)return status('Başlık zorunludur.',true);if(!state.selected){store[state.section].push(r);state.selected=r}saveStore();status('Kaydedildi. Bu tarayıcıdaki panel taslağı güncellendi.');reload()}$('#login-form').onsubmit=e=>{e.preventDefault();if($('#email').value.trim().toLowerCase()==='admin'&&$('#password').value==='milligenclikMGD'){sessionStorage.setItem('mgd-admin','1');showPanel()}else $('#login-status').textContent='Kullanıcı adı veya şifre hatalı.'};$('#logout').onclick=()=>{sessionStorage.removeItem('mgd-admin');showLogin()};document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{state.section=b.dataset.section;state.selected=null;document.querySelectorAll('[data-section]').forEach(x=>x.classList.toggle('active',x===b));setMode();reload()});$('#add').onclick=()=>{state.selected=null;fill({title:'',summary:'',status:'draft'});$('#empty').hidden=true};$('#save').onclick=save;$('#filter').oninput=renderList;['title','summary','button-label','category'].forEach(id=>$('#'+id).addEventListener('input',updatePreview));$('#image').onchange=()=>{const f=$('#image').files[0];if(f){$('#image').dataset.url=URL.createObjectURL(f);$('#preview-image').src=$('#image').dataset.url}};if(sessionStorage.getItem('mgd-admin')==='1')showPanel();else showLogin()})();
